create function public.kappy_create_conversation(p_team uuid,p_title text,p_users uuid[]) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not kappy_private.is_member(p_team) then raise exception 'Not a team member'; end if; if p_users is null or cardinality(p_users)<1 or cardinality(p_users)>50 or exists(select 1 from unnest(p_users) u where u is null or not exists(select 1 from public.kappy_members m where m.team_id=p_team and m.user_id=u)) then raise exception 'Invalid participants'; end if; insert into public.kappy_conversations(team_id,title) values(p_team,trim(p_title)) returning id into v_id; insert into public.kappy_conversation_members(conversation_id,user_id) select v_id,u from (select distinct unnest(p_users || array[auth.uid()]) as u) s; return v_id; end $$;
revoke all on function public.kappy_create_conversation(uuid,text,uuid[]) from public,anon;
grant execute on function public.kappy_create_conversation(uuid,text,uuid[]) to authenticated;